<?php
require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/workspace.php';
$user=currentUser();$pdo=db();$message='';$error='';
function ownedProfile(PDO $pdo,int $profile,int $userId):bool{$s=$pdo->prepare('SELECT 1 FROM wishlist_profiles WHERE id=? AND user_id=?');$s->execute([$profile,$userId]);return (bool)$s->fetchColumn();}
if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf($_POST['csrf']??'')){try{
  $action=$_POST['action']??'';$profile=(int)($_POST['profile_id']??0);if($profile&&!ownedProfile($pdo,$profile,(int)$user['id']))throw new RuntimeException('Invalid profile.');
  if($action==='create_profile'){$name=trim($_POST['profile_name']??'');if(!$name)throw new RuntimeException('Profile name is required.');$pdo->prepare('INSERT IGNORE INTO wishlist_profiles(user_id,name) VALUES(?,?)')->execute([$user['id'],$name]);$profile=(int)$pdo->lastInsertId()?:$profile;$message='Profile created.';}
  elseif($action==='add_candidate'){$candidate=trim($_POST['candidate_id']??'');if(!$candidate)throw new RuntimeException('Choose a candidate.');$s=$pdo->prepare('INSERT INTO wishlist_items(profile_id,candidate_id,disposition) VALUES(?,?,\'wishlist\') ON DUPLICATE KEY UPDATE disposition=IF(disposition=\'blacklisted\',disposition,\'wishlist\')');$s->execute([$profile,$candidate]);$message=$s->rowCount()?'Candidate added.':'Candidate is already in this profile.';}
  elseif($action==='set_disposition'){$candidate=$_POST['candidate_id']??'';$value=$_POST['disposition']??'';if(!in_array($value,['wishlist','selected','blacklisted'],true))throw new RuntimeException('Invalid candidate status.');$pdo->prepare('UPDATE wishlist_items wi JOIN wishlist_profiles wp ON wp.id=wi.profile_id SET wi.disposition=? WHERE wi.profile_id=? AND wi.candidate_id=? AND wp.user_id=?')->execute([$value,$profile,$candidate,$user['id']]);$message='Candidate status updated.';}
  elseif($action==='change_profile'){$candidate=$_POST['candidate_id']??'';$target=(int)($_POST['target_profile_id']??0);if(!ownedProfile($pdo,$target,(int)$user['id']))throw new RuntimeException('Choose a valid destination profile.');$pdo->beginTransaction();$pdo->prepare("INSERT INTO wishlist_items(profile_id,candidate_id,disposition) VALUES(?,?,'wishlist') ON DUPLICATE KEY UPDATE disposition=IF(disposition='blacklisted',disposition,'wishlist')")->execute([$target,$candidate]);$pdo->prepare('DELETE FROM wishlist_items WHERE profile_id=? AND candidate_id=?')->execute([$profile,$candidate]);$pdo->commit();$message='Candidate moved to another profile.';}
  elseif($action==='email'){$ids=array_values(array_unique(array_filter($_POST['candidate_ids']??[])));$subject=trim($_POST['subject']??'');$body=trim($_POST['body']??'');$date=trim($_POST['interview_date']??'');$time=trim($_POST['interview_time']??'');$timezone=trim($_POST['timezone']??'Asia/Kolkata');if(!$ids||!$subject||!$body)throw new RuntimeException('Select candidates and complete the email preview.');$interviewAt=null;if($date||$time){$dt=DateTime::createFromFormat('Y-m-d H:i',"$date $time",new DateTimeZone($timezone));if(!$dt)throw new RuntimeException('Enter a valid interview date and time.');$interviewAt=$dt->format('Y-m-d H:i:s');}
    $marks=str_repeat('?,',count($ids)-1).'?';$allowed=$pdo->prepare("SELECT candidate_id FROM wishlist_items WHERE profile_id=? AND disposition='wishlist' AND candidate_id IN ($marks)");$allowed->execute(array_merge([$profile],$ids));$allowedIds=$allowed->fetchAll(PDO::FETCH_COLUMN);$all=loadCandidateRecords();$map=[];foreach($all as $c)$map[$c['id']]=$c;$recipients=[];foreach($allowedIds as $id)if(!empty($map[$id]['email']))$recipients[$id]=$map[$id]['email'];if(!$recipients)throw new RuntimeException('No eligible selected candidate has an email address.');$dedupe=hash('sha256',$user['id'].'|'.$profile.'|'.$subject.'|'.$body.'|'.$interviewAt.'|'.implode(',',array_keys($recipients)));$status=getenv('RESUMEIQ_EMAIL_SEND')==='1'?'sending':'preview';$pdo->beginTransaction();$pdo->prepare('INSERT INTO email_batches(user_id,profile_id,subject,body,interview_at,timezone,recipient_count,status,dedupe_key) VALUES(?,?,?,?,?,?,?,?,?)')->execute([$user['id'],$profile,$subject,$body,$interviewAt,$timezone,count($recipients),$status,$dedupe]);$batch=(int)$pdo->lastInsertId();$ri=$pdo->prepare('INSERT INTO email_recipients(batch_id,candidate_id,email,status) VALUES(?,?,?,?)');foreach($recipients as $id=>$email)$ri->execute([$batch,$id,$email,$status==='preview'?'preview':'pending']);$pdo->commit();if($status==='sending'){foreach($recipients as $id=>$email){$candidate=$map[$id];$personal=strtr($body,['{{candidate_name}}'=>candidatePresentation($candidate)['name'],'{{interview_date}}'=>$date,'{{interview_time}}'=>$time,'{{timezone}}'=>$timezone]);$headers="MIME-Version: 1.0\r\nContent-Type: text/plain; charset=UTF-8\r\nFrom: no-reply@resumeiq.local";$ok=@mail($email,$subject,$personal,$headers);$pdo->prepare('UPDATE email_recipients SET status=?,sent_at=IF(?,NOW(),NULL),error_text=? WHERE batch_id=? AND candidate_id=?')->execute([$ok?'sent':'failed',$ok?1:0,$ok?null:'mail() failed',$batch,$id]);}$pdo->prepare("UPDATE email_batches SET status='completed' WHERE id=?")->execute([$batch]);}$message=$status==='preview'?'Email preview saved. Real sending remains disabled.':'Email batch processed.';}
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=str_contains($e->getMessage(),'Duplicate entry')?'This exact email preview already exists.':$e->getMessage();}}
$profilesStmt=$pdo->prepare("SELECT wp.*,COUNT(wi.id) total,SUM(wi.disposition='wishlist') active_count,SUM(wi.disposition='selected') selected_count,SUM(wi.disposition='blacklisted') blocked_count FROM wishlist_profiles wp LEFT JOIN wishlist_items wi ON wi.profile_id=wp.id WHERE wp.user_id=? GROUP BY wp.id ORDER BY wp.created_at DESC");$profilesStmt->execute([$user['id']]);$profiles=$profilesStmt->fetchAll();$activeProfile=(int)($_GET['profile']??$_POST['profile_id']??($profiles[0]['id']??0));$includeSelected=isset($_GET['include_selected']);$showBlocked=isset($_GET['show_blocked']);$allCandidates=loadCandidateRecords();$candidateMap=[];foreach($allCandidates as $c)$candidateMap[$c['id']]=$c;$rows=[];$existing=[];if($activeProfile){$s=$pdo->prepare('SELECT candidate_id,disposition FROM wishlist_items WHERE profile_id=?');$s->execute([$activeProfile]);foreach($s->fetchAll() as $row){$existing[$row['candidate_id']]=$row['disposition'];if(isset($candidateMap[$row['candidate_id']]))$rows[]=array_merge($candidateMap[$row['candidate_id']],['disposition'=>$row['disposition']]);}usort($rows,fn($a,$b)=>$b['score']<=>$a['score']);}
$visible=array_values(array_filter($rows,fn($x)=>$x['disposition']==='wishlist'||($includeSelected&&$x['disposition']==='selected')||($showBlocked&&$x['disposition']==='blacklisted')));
$activePage='wishlist';$pageTitle='Wishlist · ResumeIQ';$pageStyles='<style>.profile-strip{display:flex;gap:8px;overflow-x:auto;margin:12px 0;padding-bottom:3px}.profile-card{min-width:210px;padding:13px;border:1px solid var(--line);background:#fff;border-radius:10px}.profile-card.active{border-color:#cfc4ff;background:var(--primary-soft)}.profile-card strong{display:block;font-size:11px}.profile-card span{font-size:9px;color:var(--muted)}.wish-toolbar{display:grid;grid-template-columns:1fr 210px auto;gap:8px;padding:14px}.wish-layout{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(330px,.85fr);gap:10px}.wish-list,.preview{padding:16px}.wish-row{display:grid;grid-template-columns:26px minmax(130px,1fr) 58px 120px auto;gap:9px;align-items:center;padding:11px 0;border-bottom:1px solid var(--line)}.wish-row p{margin:3px 0;color:var(--muted);font-size:9px}.row-actions{display:flex;gap:5px}.mini{width:30px;height:30px;border:1px solid var(--line);background:#fff;border-radius:7px;color:var(--muted)}.mini.danger{color:var(--danger)}.filters{display:flex;gap:12px;font-size:10px;margin:0 0 12px}.preview h2,.wish-list h2{font-size:13px;margin:0 0 12px}.preview-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.preview textarea{min-height:150px}.mail-actions{display:flex;justify-content:space-between;gap:8px;margin-top:10px}.notice{padding:10px;border-radius:8px;margin:10px 0;font-size:10px}.ok{background:var(--green-soft);color:var(--green)}.err{background:#fff1f3;color:var(--danger)}@media(max-width:900px){.wish-layout{grid-template-columns:1fr}.wish-toolbar{grid-template-columns:1fr}.wish-row{grid-template-columns:26px 1fr 54px}.wish-row>select,.row-actions{grid-column:2/-1}}</style>';require __DIR__.'/views/partials/header.php';?>
<section class="page-head"><div><div class="kicker"><i class="fa-solid fa-heart"></i> Role-based talent lists</div><h1>Wishlist profiles</h1><p>Select a profile, review scores, prepare an interview email, or move and block candidates.</p></div><form method="post" style="display:flex;gap:8px"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="action" value="create_profile"><input class="control" name="profile_name" placeholder="New job profile" required><button class="btn btn-primary"><i class="fa-solid fa-plus"></i>Create</button></form></section>
<?php if($message):?><div class="notice ok"><?=htmlspecialchars($message)?></div><?php endif?><?php if($error):?><div class="notice err"><?=htmlspecialchars($error)?></div><?php endif?>
<nav class="profile-strip"><?php foreach($profiles as $p):?><a class="profile-card <?=$activeProfile===(int)$p['id']?'active':''?>" href="?profile=<?=$p['id']?>"><strong><?=htmlspecialchars($p['name'])?></strong><span><?=(int)$p['active_count']?> active · <?=(int)$p['selected_count']?> selected · <?=(int)$p['blocked_count']?> blocked</span></a><?php endforeach?></nav>
<?php if($activeProfile):?><section class="panel wish-toolbar"><input class="control" id="wishSearch" placeholder="Search candidates"><form method="post" style="display:contents"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="action" value="add_candidate"><input type="hidden" name="profile_id" value="<?=$activeProfile?>"><select class="control" name="candidate_id" required><option value="">Add candidate…</option><?php foreach($allCandidates as $c):if(isset($existing[$c['id']]))continue;$d=candidatePresentation($c);?><option value="<?=htmlspecialchars($c['id'])?>"><?=htmlspecialchars($d['name'])?> · <?=$c['score']?>%</option><?php endforeach?></select><button class="btn"><i class="fa-solid fa-user-plus"></i>Add</button></form></section>
<div class="filters"><a href="?profile=<?=$activeProfile?><?=$includeSelected?'':'&include_selected=1'?>"><i class="fa-<?=$includeSelected?'solid fa-square-check':'regular fa-square'?>"></i> Include selected</a><a href="?profile=<?=$activeProfile?><?=$showBlocked?'':'&show_blocked=1'?>"><i class="fa-<?=$showBlocked?'solid fa-square-check':'regular fa-square'?>"></i> Show blacklist</a></div>
<section class="wish-layout"><article class="panel wish-list"><h2>Candidates</h2><?php if(!$visible):?><div class="empty">No candidates match this view.</div><?php endif?><form method="post" id="mailForm"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="action" value="email"><input type="hidden" name="profile_id" value="<?=$activeProfile?>"><?php foreach($visible as $c):$d=candidatePresentation($c);?><div class="wish-row" data-find="<?=htmlspecialchars(strtolower($d['name'].' '.$d['role'].' '.($c['email']??'')))?>"><input type="checkbox" name="candidate_ids[]" value="<?=htmlspecialchars($c['id'])?>" <?=$c['disposition']!=='wishlist'?'disabled':''?>><div><strong><?=htmlspecialchars($d['name'])?></strong><p><?=htmlspecialchars($d['role'])?> · <?=htmlspecialchars($c['email']??'No email')?> · <?=htmlspecialchars(ucfirst($c['disposition']))?></p></div><span class="badge"><?=$c['score']?>%</span><select class="control" onchange="moveCandidate(this,'<?=htmlspecialchars($c['id'])?>')"><option value="">Change profile</option><?php foreach($profiles as $p):if((int)$p['id']===$activeProfile)continue;?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach?></select><div class="row-actions"><?php if($c['disposition']!=='selected'):?><button class="mini" type="button" title="Mark selected" onclick="setStatus('<?=htmlspecialchars($c['id'])?>','selected')"><i class="fa-solid fa-check"></i></button><?php else:?><button class="mini" type="button" title="Return to wishlist" onclick="setStatus('<?=htmlspecialchars($c['id'])?>','wishlist')"><i class="fa-solid fa-rotate-left"></i></button><?php endif?><?php if($c['disposition']!=='blacklisted'):?><button class="mini danger" type="button" title="Blacklist" onclick="setStatus('<?=htmlspecialchars($c['id'])?>','blacklisted')"><i class="fa-solid fa-ban"></i></button><?php else:?><button class="mini" type="button" title="Remove from blacklist" onclick="setStatus('<?=htmlspecialchars($c['id'])?>','wishlist')"><i class="fa-solid fa-unlock"></i></button><?php endif?></div></div><?php endforeach?></form></article>
<aside class="panel preview"><h2>Email and interview preview</h2><label>Subject</label><input class="control" form="mailForm" name="subject" value="Interview invitation" required><div class="preview-grid"><div><label>Date</label><input class="control" form="mailForm" type="date" name="interview_date"></div><div><label>Time</label><input class="control" form="mailForm" type="time" name="interview_time"></div></div><label>Timezone</label><select class="control" form="mailForm" name="timezone"><option>Asia/Kolkata</option><option>UTC</option><option>America/New_York</option><option>Europe/London</option></select><label>Message</label><textarea class="control" form="mailForm" name="body" required>Hello {{candidate_name}},&#10;&#10;We would like to invite you for an interview on {{interview_date}} at {{interview_time}} ({{timezone}}).&#10;&#10;Regards,&#10;ResumeIQ Hiring Team</textarea><div class="mail-actions"><button type="button" class="btn" onclick="document.querySelectorAll('#mailForm [name=&quot;candidate_ids[]&quot;]:not(:disabled)').forEach((x,i)=>x.checked=i<5)"><i class="fa-solid fa-ranking-star"></i>Top 5</button><button class="btn btn-primary" form="mailForm"><i class="fa-solid fa-paper-plane"></i>Save / send preview</button></div></aside></section><?php else:?><div class="empty">Create a profile to begin.</div><?php endif?>
<form method="post" id="actionForm" hidden><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="profile_id" value="<?=$activeProfile?>"><input name="action"><input name="candidate_id"><input name="disposition"><input name="target_profile_id"></form><script>const af=document.getElementById('actionForm');function setStatus(id,status){if(status==='blacklisted'&&!confirm('Blacklist this candidate for this profile?'))return;af.action.value='set_disposition';af.candidate_id.value=id;af.disposition.value=status;af.submit()}function moveCandidate(select,id){if(!select.value)return;af.action.value='change_profile';af.candidate_id.value=id;af.target_profile_id.value=select.value;af.submit()}document.getElementById('wishSearch')?.addEventListener('input',e=>document.querySelectorAll('.wish-row').forEach(r=>r.style.display=r.dataset.find.includes(e.target.value.toLowerCase())?'grid':'none'));</script>
<script>document.querySelectorAll('.wish-row').forEach((row,i)=>{const label=document.createElement('span');label.className='tag';label.textContent=i<5?'Primary '+(i+1):i<10?'Substitute '+(i-4):'Reserve';row.querySelector('div').appendChild(label)});</script>
